// SPDX-License-Identifier: GPL-3.0-or-later

pragma solidity ^0.8.24;

import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {IBancorFormula} from "./interfaces/IBancorFormula.sol";
import {AccessControlUpgradeable} from "@openzeppelin/contracts-upgradeable/access/AccessControlUpgradeable.sol";

import {SecurityModule} from "./SecurityModule.sol";
import {ITokenManager} from "./interfaces/ITokenManager.sol";
import {IERC20Extended} from "./interfaces/IERC20Extended.sol";
import {IVault} from "./interfaces/IVault.sol";
import {IMoxieBondingCurve} from "./interfaces/IMoxieBondingCurve.sol";

/**
 * @title Moxie Bonding curve
 * @author Moxie Team
 * @notice Bonding curve contract which enables subject onboarding, buy & sell of subject shares.
 */
contract MoxieBondingCurve is IMoxieBondingCurve, SecurityModule {
    using SafeERC20 for IERC20Extended;

    bytes32 public constant UPDATE_FEES_ROLE = keccak256("UPDATE_FEES_ROLE");
    bytes32 public constant UPDATE_FORMULA_ROLE =
        keccak256("UPDATE_FORMULA_ROLE");
    bytes32 public constant UPDATE_BENEFICIARY_ROLE =
        keccak256("UPDATE_BENEFICIARY_ROLE");

    error MoxieBondingCurve_InvalidToken();
    error MoxieBondingCurve_InvalidVault();
    error MoxieBondingCurve_InvalidBeneficiary();
    error MoxieBondingCurve_InvalidFeePercentage();
    error MoxieBondingCurve_InvalidFormula();
    error MoxieBondingCurve_InvalidTokenManager();
    error MoxieBondingCurve_InvalidOwner();
    error MoxieBondingCurve_InvalidSubjectFactory();
    error MoxieBondingCurve_OnlySubjectFactory();
    error MoxieBondingCurve_InvalidReserveRation();
    error MoxieBondingCurve_SubjectAlreadyInitialized();
    error MoxieBondingCurve_SubjectNotInitialized();
    error MoxieBondingCurve_InvalidSubjectSupply();
    error MoxieBondingCurve_InvalidSubject();
    error MoxieBondingCurve_InvalidDepositAmount();
    error MoxieBondingCurve_InvalidSubjectToken();
    error MoxieBondingCurve_SlippageExceedsLimit();
    error MoxieBondingCurve_InvalidSellAmount();
    error MoxieBondingCurve_InvalidAmount();

    event UpdateFees(
        uint256 _protocolBuyFeePct,
        uint256 _protocolSellFeePct,
        uint256 _subjectBuyFeePct,
        uint256 _subjectSellFeePct
    );

    event UpdateBeneficiary(address _beneficiary);

    event UpdateFormula(address _formula);

    event BondingCurveInitialized(
        address indexed _subject,
        address indexed _subjectToken,
        uint256 _initialSupply,
        uint256 _reserve,
        uint32 _reserveRatio
    );

    event SubjectSharePurchased(
        address indexed _subject,
        address indexed _sellToken,
        uint256 _sellAmount,
        address _spender,
        address _buyToken,
        uint256 _buyAmount,
        address indexed _beneficiary
    );

    event SubjectShareSold(
        address indexed _subject,
        address indexed _sellToken,
        uint256 _sellAmount,
        address _spender,
        address _buyToken,
        uint256 _buyAmount,
        address indexed _beneficiary
    );
    /// @dev Address of moxie token.
    IERC20Extended public token;
    /// @dev address of Bancors formula.
    IBancorFormula public formula;
    /// @dev Address of token manager contracts.
    ITokenManager public tokenManager;
    /// @dev Address of vault contract.
    IVault public vault;

    /// @dev Use to represent fee percentage base 0% = 0; 1% = 10 ** 16; 100% = 10 ** 18
    uint256 public constant PCT_BASE = 10 ** 18;
    /// @dev Use to represent reserve ratio, 1M is 1
    uint32 public constant PPM = 1000000;

    /// @dev Fee settings.
    uint256 public protocolBuyFeePct;
    uint256 public protocolSellFeePct;
    uint256 public subjectBuyFeePct;
    uint256 public subjectSellFeePct;

    /// @dev Address of protocol fee beneficiary.
    address public feeBeneficiary;

    /// @dev Address of subject factory.
    address public subjectFactory;

    /// @dev subject address vs reserve ratio
    mapping(address subject => uint32 _reserveRatio) public reserveRatio;

    /**
     * Initialize the contract.
     * @param _token Moxie token address.
     * @param _formula Bancors formula contract address.
     * @param _owner Owner of contract.
     * @param _tokenManager Address of token manager contract.
     * @param _vault Address of vault contract address.
     * @param _feeInput subject & protocol Feeinput struct.
     * @param _feeBeneficiary Protocol fee beneficiary.
     * @param _subjectFactory Subject Factory address.
     */
    function initialize(
        address _token,
        address _formula,
        address _owner,
        address _tokenManager,
        address _vault,
        FeeInput memory _feeInput,
        address _feeBeneficiary,
        address _subjectFactory
    ) external initializer {
        __AccessControl_init();
        __Pausable_init();

        _validateInput(
            _token,
            _formula,
            _owner,
            _tokenManager,
            _vault,
            _feeBeneficiary,
            _subjectFactory
        );

        _validateFee(_feeInput);

        token = IERC20Extended(_token);
        formula = IBancorFormula(_formula);
        tokenManager = ITokenManager(_tokenManager);
        vault = IVault(_vault);
        protocolBuyFeePct = _feeInput.protocolBuyFeePct;
        protocolSellFeePct = _feeInput.protocolSellFeePct;
        subjectBuyFeePct = _feeInput.subjectBuyFeePct;
        subjectSellFeePct = _feeInput.subjectSellFeePct;
        feeBeneficiary = _feeBeneficiary;
        subjectFactory = _subjectFactory;

        _grantRole(DEFAULT_ADMIN_ROLE, _owner);
    }

    /**
     * @dev Internal function to validate initialization input.
     * @param _token Address of moxie token.
     * @param _formula Address of formula contract address.
     * @param _owner Address of owner.
     * @param _tokenManager  Address of token manager.
     * @param _vault Address of vault.
     * @param _feeBeneficiary Address of fee beneficiary.
     * @param _subjectFactory Address of subject factory.
     */
    function _validateInput(
        address _token,
        address _formula,
        address _owner,
        address _tokenManager,
        address _vault,
        address _feeBeneficiary,
        address _subjectFactory
    ) internal pure {
        if (_isZeroAddress(_token)) revert MoxieBondingCurve_InvalidToken();
        if (_isZeroAddress(_formula)) revert MoxieBondingCurve_InvalidFormula();
        if (_isZeroAddress(_owner)) revert MoxieBondingCurve_InvalidOwner();
        if (_isZeroAddress(_tokenManager))
            revert MoxieBondingCurve_InvalidTokenManager();
        if (_isZeroAddress(_vault)) revert MoxieBondingCurve_InvalidVault();
        if (_isZeroAddress(_subjectFactory))
            revert MoxieBondingCurve_InvalidSubjectFactory();
        if (_isZeroAddress(_feeBeneficiary))
            revert MoxieBondingCurve_InvalidBeneficiary();
    }

    /**
     * Internal function to validate Fee params.
     * @param _feeInput Fee input struct.
     */
    function _validateFee(FeeInput memory _feeInput) internal pure {
        if (
            !_feeIsValid(
                _feeInput.protocolBuyFeePct + _feeInput.subjectBuyFeePct
            ) ||
            !_feeIsValid(
                _feeInput.protocolSellFeePct + _feeInput.subjectSellFeePct
            )
        ) revert MoxieBondingCurve_InvalidFeePercentage();
    }

    /**
     * @dev Internal function to update fee beneficiary.
     * @param _beneficiary Address of fee beneficiary.
     */
    function _updateFeeBeneficiary(address _beneficiary) internal {
        feeBeneficiary = _beneficiary;

        emit UpdateBeneficiary(_beneficiary);
    }

    /**
     * @dev Internal function to update bancor formula.
     * @param _formula Address of formula contract address.
     */
    function _updateFormula(IBancorFormula _formula) internal {
        formula = _formula;

        emit UpdateFormula(address(_formula));
    }

    /**
     * @dev Internal function to validate fee.
     * @param _fee Fee Input in PCT_Base.
     */
    function _feeIsValid(uint256 _fee) internal pure returns (bool) {
        return _fee < PCT_BASE;
    }

    /**
     * @dev Internal function to validate address.
     * @param _address  Address to validate.
     */
    function _isZeroAddress(address _address) internal pure returns (bool) {
        return _address == address(0);
    }

    /**
     * @dev Internal function to validate reserve ratio.
     * @param _reserveRatio Reserve ratio in PPM.
     */
    function _reserveRatioIsValid(
        uint32 _reserveRatio
    ) internal pure returns (bool) {
        return _reserveRatio <= PPM;
    }

    /**
     * @dev Internal function to update fee.
     * @param _protocolBuyFeePct Protocol fee percentage applied during buy share transaction.
     * @param _protocolSellFeePct Subject fee percentage applied during sell share transaction.
     * @param _subjectBuyFeePct Subject fee percentage applied during buy share transaction.
     * @param _subjectSellFeePct Subject fee percentage applied during sell share transaction.
     */
    function _updateFees(
        uint256 _protocolBuyFeePct,
        uint256 _protocolSellFeePct,
        uint256 _subjectBuyFeePct,
        uint256 _subjectSellFeePct
    ) internal {
        protocolBuyFeePct = _protocolBuyFeePct;
        protocolSellFeePct = _protocolSellFeePct;
        subjectBuyFeePct = _subjectBuyFeePct;
        subjectSellFeePct = _subjectSellFeePct;

        emit UpdateFees(
            protocolBuyFeePct,
            protocolSellFeePct,
            subjectBuyFeePct,
            subjectSellFeePct
        );
    }

    /**
     * @dev Internal function to buy  shares of subject.
     * @param _subjectToken Address of Subject Token.
     * @param _depositAmount Amount of deposit to buy shares.
     * @param _onBehalfOf Address of beneficiary where shares will be minted. This address can be zero address too.
     * @param _minReturnAmountAfterFee Minimum number of shares that must be received.
     * @param _subject Address of subject.
     * @param _subjectReserveRatio Subject Reserve ratio.
     */
    function _buyShares(
        IERC20Extended _subjectToken,
        uint256 _depositAmount,
        address _onBehalfOf,
        uint256 _minReturnAmountAfterFee,
        address _subject,
        uint32 _subjectReserveRatio
    ) internal returns (uint256 shares_) {
        // moxie
        token.safeTransferFrom(msg.sender, address(this), _depositAmount);
        {
            //to solve stack too deep issue.
            (uint256 protocolFee, uint256 subjectFee) = _calculateBuySideFee(
                _depositAmount
            );

            token.safeTransfer(_subject, subjectFee);
            token.safeTransfer(feeBeneficiary, protocolFee);
            uint256 vaultDeposit = _depositAmount - subjectFee - protocolFee;

            token.approve(address(vault), vaultDeposit);
            uint256 subjectReserve = vault.balanceOf(
                address(_subjectToken),
                address(token)
            );

            vault.deposit(address(_subjectToken), address(token), vaultDeposit);

            shares_ = formula.calculatePurchaseReturn(
                _subjectToken.totalSupply(),
                subjectReserve,
                _subjectReserveRatio,
                vaultDeposit
            );
        }

        if (shares_ < _minReturnAmountAfterFee)
            revert MoxieBondingCurve_SlippageExceedsLimit();

        ///@dev Don't mint if intent is to burn
        if (!_isZeroAddress(_onBehalfOf)) {
            tokenManager.mint(_subject, _onBehalfOf, shares_);
        }

        emit SubjectSharePurchased(
            _subject,
            address(token),
            _depositAmount,
            msg.sender,
            address(_subjectToken),
            shares_,
            _onBehalfOf
        );
    }

    /**
     * @dev Internal function to sell  shares of subject.
     * @param _subjectToken Address of Subject Token.
     * @param _sellAmount Amount of shares to sell.
     * @param _onBehalfOf Address of beneficiary where funds will be returned.
     * @param _minReturnAmountAfterFee Minimum amount of funds that should be returned.
     * @param _subject Address of subject.
     * @param _subjectReserveRatio Subject Reserve ratio.
     */
    function _sellShares(
        IERC20Extended _subjectToken,
        uint256 _sellAmount,
        address _onBehalfOf,
        uint256 _minReturnAmountAfterFee,
        address _subject,
        uint32 _subjectReserveRatio
    ) internal returns (uint256 returnedAmount_) {
        uint256 subjectReserve = vault.balanceOf(
            address(_subjectToken),
            address(token)
        );

        uint256 returnAmountWithoutFee = formula.calculateSaleReturn(
            _subjectToken.totalSupply(),
            subjectReserve,
            _subjectReserveRatio,
            _sellAmount
        );

        (uint256 protocolFee, uint256 subjectFee) = _calculateSellSideFee(
            returnAmountWithoutFee
        );

        returnedAmount_ = returnAmountWithoutFee - subjectFee - protocolFee;
        if (returnedAmount_ < _minReturnAmountAfterFee)
            revert MoxieBondingCurve_SlippageExceedsLimit();
        emit SubjectShareSold(
            _subject,
            address(_subjectToken),
            _sellAmount,
            msg.sender,
            address(token),
            returnedAmount_,
            _onBehalfOf
        );

        // burn subjectToken
        _subjectToken.burnFrom(msg.sender, _sellAmount);

        vault.transfer(
            address(_subjectToken),
            address(token),
            address(this),
            returnAmountWithoutFee
        );

        token.safeTransfer(_subject, subjectFee);
        token.safeTransfer(feeBeneficiary, protocolFee);
        token.safeTransfer(_onBehalfOf, returnedAmount_);
    }

    /**
     * @dev Internal function to calculate buy side fee.
     * @param _depositAmount Deposit amount for buy.
     * @return protocolFee_ Buy side protocol fee in PCT_BASE.
     * @return subjectFee_  Buy side subject fee in PCT_BASE.
     */
    function _calculateBuySideFee(
        uint256 _depositAmount
    ) internal view returns (uint256 protocolFee_, uint256 subjectFee_) {
        protocolFee_ = (_depositAmount * protocolBuyFeePct) / PCT_BASE;
        subjectFee_ = (_depositAmount * subjectBuyFeePct) / PCT_BASE;
    }

    /**
     * @dev Internal function to calculate sell side fee.
     * @param _sellAmount Amount of subject shares to sell.
     * @return protocolFee_ Sell side protocol fee in PCT_BASE.
     * @return subjectFee_ Sell side subject fee in PCT_BASE.
     */
    function _calculateSellSideFee(
        uint256 _sellAmount
    ) internal view returns (uint256 protocolFee_, uint256 subjectFee_) {
        protocolFee_ = (_sellAmount * protocolSellFeePct) / PCT_BASE;
        subjectFee_ = (_sellAmount * subjectSellFeePct) / PCT_BASE;
    }

    function _sellSharesInternal(
        address _subject,
        uint256 _sellAmount,
        address _onBehalfOf,
        uint256 _minReturnAmountAfterFee
    ) internal whenNotPaused returns (uint256 returnAmount_) {
        if (_isZeroAddress(_subject)) revert MoxieBondingCurve_InvalidSubject();
        if (_sellAmount == 0) revert MoxieBondingCurve_InvalidSellAmount();

        uint32 subjectReserveRatio = reserveRatio[_subject];

        if (subjectReserveRatio == 0)
            revert MoxieBondingCurve_SubjectNotInitialized();

        IERC20Extended subjectToken = IERC20Extended(
            tokenManager.tokens(_subject)
        );

        if (_isZeroAddress(address(subjectToken)))
            revert MoxieBondingCurve_InvalidSubjectToken();

        returnAmount_ = _sellShares(
            subjectToken,
            _sellAmount,
            _onBehalfOf,
            _minReturnAmountAfterFee,
            _subject,
            subjectReserveRatio
        );
    }

    function _buySharesInternal(
        address _subject,
        uint256 _depositAmount,
        address _onBehalfOf,
        uint256 _minReturnAmountAfterFee
    ) internal returns (uint256 shares_) {
        if (_isZeroAddress(_subject)) revert MoxieBondingCurve_InvalidSubject();
        if (_depositAmount == 0)
            revert MoxieBondingCurve_InvalidDepositAmount();

        uint32 subjectReserveRatio = reserveRatio[_subject];

        if (subjectReserveRatio == 0)
            revert MoxieBondingCurve_SubjectNotInitialized();

        IERC20Extended subjectToken = IERC20Extended(
            tokenManager.tokens(_subject)
        );

        if (_isZeroAddress(address(subjectToken)))
            revert MoxieBondingCurve_InvalidSubjectToken();

        shares_ = _buyShares(
            subjectToken,
            _depositAmount,
            _onBehalfOf,
            _minReturnAmountAfterFee,
            _subject,
            subjectReserveRatio
        );
    }

    /**
     * @notice Validates Subject Input
     * @param _subject  Address of subject
     * @param _subjectTokenAmount Amount of buy/sell estimates.
     * @return subjectReserveRatio_ Reserve ratio of subject.
     * @return subjectReserve_ Total reserve of Subject.
     * @return subjectSupply_ Total supply of subject token.
     */
    function _validateSubjectInput(
        address _subject,
        uint256 _subjectTokenAmount
    )
        internal
        view
        returns (
            uint32 subjectReserveRatio_,
            uint256 subjectReserve_,
            uint256 subjectSupply_
        )
    {
        if (_isZeroAddress(_subject)) revert MoxieBondingCurve_InvalidSubject();
        if (_subjectTokenAmount == 0) revert MoxieBondingCurve_InvalidAmount();

        subjectReserveRatio_ = reserveRatio[_subject];

        if (subjectReserveRatio_ == 0)
            revert MoxieBondingCurve_SubjectNotInitialized();

        IERC20Extended subjectToken = IERC20Extended(
            tokenManager.tokens(_subject)
        );

        subjectReserve_ = vault.balanceOf(
            address(subjectToken),
            address(token)
        );

        subjectSupply_ = subjectToken.totalSupply();
    }

    /**
     * @notice Update fee only be called by role UPDATE_FEES_ROLE.
     * @param _feeInput Fee input struct.
     */
    function updateFees(
        FeeInput memory _feeInput
    ) external onlyRole(UPDATE_FEES_ROLE) {
        _validateFee(_feeInput);

        _updateFees(
            _feeInput.protocolBuyFeePct,
            _feeInput.protocolSellFeePct,
            _feeInput.subjectBuyFeePct,
            _feeInput.subjectSellFeePct
        );
    }

    /**
     * @notice Update formula to `_formula`. It can be done by UPDATE_FORMULA_ROLE.
     * @param _formula The address of the new BancorFormula [computation] contract
     */
    function updateFormula(
        address _formula
    ) external onlyRole(UPDATE_FORMULA_ROLE) {
        if (_isZeroAddress(_formula)) revert MoxieBondingCurve_InvalidFormula();

        _updateFormula(IBancorFormula(_formula));
    }

    /**
     * @notice Update beneficiary to `_beneficiary. It can be done by UPDATE_BENEFICIARY_ROLE.
     * @param _feeBeneficiary The address of the new beneficiary [to whom fees are to be sent]
     */
    function updateFeeBeneficiary(
        address _feeBeneficiary
    ) external onlyRole(UPDATE_BENEFICIARY_ROLE) {
        if (_isZeroAddress(_feeBeneficiary))
            revert MoxieBondingCurve_InvalidBeneficiary();

        _updateFeeBeneficiary(_feeBeneficiary);
    }

    /**
     * @notice Initialize Bonding curve for subject, it's called by subject factory.
     * @param _subject Address of subject.
     * @param _initialSupply Initial supply of subjects tokens at the time of bonding curve initialization.
     * @param _reserveRatio reserve ratio of subject for bonding curve.
     * @param _reserveAmount Initial reserve amount.
     */
    function initializeSubjectBondingCurve(
        address _subject,
        uint32 _reserveRatio,
        uint256 _initialSupply,
        uint256 _reserveAmount
    ) external whenNotPaused returns (bool) {
        if (_isZeroAddress(_subject)) revert MoxieBondingCurve_InvalidSubject();

        if (msg.sender != subjectFactory)
            revert MoxieBondingCurve_OnlySubjectFactory();

        if (!_reserveRatioIsValid(_reserveRatio))
            revert MoxieBondingCurve_InvalidReserveRation();

        if (reserveRatio[_subject] != 0)
            revert MoxieBondingCurve_SubjectAlreadyInitialized();
        reserveRatio[_subject] = _reserveRatio;

        address subjectToken = tokenManager.tokens(_subject);

        if (_isZeroAddress(subjectToken))
            revert MoxieBondingCurve_InvalidSubjectToken();

        emit BondingCurveInitialized(
            _subject,
            subjectToken,
            _initialSupply,
            _reserveAmount,
            _reserveRatio
        );
        uint256 supply = IERC20Extended(subjectToken).totalSupply();
        if (_initialSupply != supply)
            revert MoxieBondingCurve_InvalidSubjectSupply();

        token.safeTransferFrom(msg.sender, address(this), _reserveAmount);
        token.approve(address(vault), _reserveAmount);
        vault.deposit(subjectToken, address(token), _reserveAmount);

        return true;
    }

    /**
     * @dev Buy shares of subject.
     * @param _subject Address of subject.
     * @param _depositAmount Deposit amount to buy shares.
     * @param _onBehalfOf  Beneficiary where shares will be minted.
     * @param _minReturnAmountAfterFee Minimum shares that must be returned.
     */
    function buySharesFor(
        address _subject,
        uint256 _depositAmount,
        address _onBehalfOf,
        uint256 _minReturnAmountAfterFee
    ) external whenNotPaused returns (uint256 shares_) {
        shares_ = _buySharesInternal(
            _subject,
            _depositAmount,
            _onBehalfOf,
            _minReturnAmountAfterFee
        );
    }

    /**
     * @dev Buy shares of subject.
     * @param _subject Address of subject.
     * @param _depositAmount Deposit amount to buy shares.
     * @param _minReturnAmountAfterFee Minimum shares that must be returned.
     */
    function buyShares(
        address _subject,
        uint256 _depositAmount,
        uint256 _minReturnAmountAfterFee
    ) external whenNotPaused returns (uint256 shares_) {
        shares_ = _buySharesInternal(
            _subject,
            _depositAmount,
            msg.sender,
            _minReturnAmountAfterFee
        );
    }

    /**
     * @dev Sell shares of subject.
     * @param _subject Address of subject.
     * @param _sellAmount Amount of subject shares to sell.
     * @param _onBehalfOf Address of buy token beneficiary.
     * @param _minReturnAmountAfterFee Minimum buy token that must be returned.
     */
    function sellSharesFor(
        address _subject,
        uint256 _sellAmount,
        address _onBehalfOf,
        uint256 _minReturnAmountAfterFee
    ) external whenNotPaused returns (uint256 returnAmount_) {
        returnAmount_ = _sellSharesInternal(
            _subject,
            _sellAmount,
            _onBehalfOf,
            _minReturnAmountAfterFee
        );
    }

    /**
     * @dev Sell shares of subject.
     * @param _subject Address of subject.
     * @param _sellAmount Amount of subject shares to sell.
     * @param _minReturnAmountAfterFee Minimum buy token that must be returned.
     */
    function sellShares(
        address _subject,
        uint256 _sellAmount,
        uint256 _minReturnAmountAfterFee
    ) external whenNotPaused returns (uint256 returnAmount_) {
        returnAmount_ = _sellSharesInternal(
            _subject,
            _sellAmount,
            msg.sender,
            _minReturnAmountAfterFee
        );
    }

    /**
     * @notice Estimates amount of Moxie token required to buy given subject token amount
     * @param _subject  Address of subject.
     * @param _subjectTokenAmount  Amount of subject tokens.
     */
    function calculateTokensForBuy(
        address _subject,
        uint256 _subjectTokenAmount
    )
        external
        view
        returns (
            uint256 moxieAmount_,
            uint256 protocolFee_,
            uint256 subjectFee_
        )
    {
        (
            uint32 subjectReserveRatio_,
            uint256 subjectReserve_,
            uint256 subjectSupply_
        ) = _validateSubjectInput(_subject, _subjectTokenAmount);

        uint256 estimatedAmount = formula.calculateFundCost(
            subjectSupply_,
            subjectReserve_,
            subjectReserveRatio_,
            _subjectTokenAmount
        );

        uint256 totalFeePCT = protocolBuyFeePct + subjectBuyFeePct;
        moxieAmount_ = (estimatedAmount * PCT_BASE) / (PCT_BASE - totalFeePCT);

        (protocolFee_, subjectFee_) = _calculateBuySideFee(moxieAmount_);
    }

    /**
     * @notice Estimates amount of Moxie tokes will be returned after selling given subject tokens.
     * @param _subject  Address of subject.
     * @param _subjectTokenAmount  Amount of subject tokens.
     */
    function calculateTokensForSell(
        address _subject,
        uint256 _subjectTokenAmount
    )
        external
        view
        returns (
            uint256 moxieAmount_,
            uint256 protocolFee_,
            uint256 subjectFee_
        )
    {
        (
            uint32 subjectReserveRatio_,
            uint256 subjectReserve_,
            uint256 subjectSupply_
        ) = _validateSubjectInput(_subject, _subjectTokenAmount);

        uint256 estimatedAmount = formula.calculateSaleReturn(
            subjectSupply_,
            subjectReserve_,
            subjectReserveRatio_,
            _subjectTokenAmount
        );

        (protocolFee_, subjectFee_) = _calculateSellSideFee(estimatedAmount);

        moxieAmount_ = estimatedAmount - protocolFee_ - subjectFee_;
    }
}

contracts/SecurityModule.sol.content:
// SPDX-License-Identifier: GPL-3.0-or-later
pragma solidity ^0.8.24;

import {AccessControlUpgradeable} from "@openzeppelin/contracts-upgradeable/access/AccessControlUpgradeable.sol";
import {PausableUpgradeable} from "@openzeppelin/contracts-upgradeable/utils/PausableUpgradeable.sol";

contract SecurityModule is AccessControlUpgradeable, PausableUpgradeable {
    bytes32 public constant PAUSE_ROLE = keccak256("PAUSE_ROLE");

    function pause() public onlyRole(PAUSE_ROLE) {
        _pause();
    }

    function unpause() public onlyRole(PAUSE_ROLE) {
        _unpause();
    }
}

contracts/Staking.sol.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.24;

import {IMoxieBondingCurve} from "./interfaces/IMoxieBondingCurve.sol";
import {SecurityModule} from "./SecurityModule.sol";
import {ITokenManager} from "./interfaces/ITokenManager.sol";
import {IERC20Extended} from "./interfaces/IERC20Extended.sol";
import {IStaking} from "./interfaces/IStaking.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

/**
 * @title Staking
 * @author Moxie Team
 * @notice Staking contract allows staking of subject tokens for a lock period.
 */
contract Staking is IStaking, SecurityModule {
    using SafeERC20 for IERC20Extended;

    bytes32 public constant CHANGE_LOCK_DURATION =
        keccak256("CHANGE_LOCK_DURATION");

    ITokenManager public tokenManager;
    IMoxieBondingCurve public moxieBondingCurve;
    IERC20Extended public moxieToken;

    uint256 public lockCount;

    mapping(uint256 lockId => LockInfo lockInfo) public locks;
    mapping(uint256 lockPeriodInSec => bool allowed) public lockPeriodsInSec;

    /**
     * @dev function to initialize the contract.
     * @param _tokenManager  Address of the token manager.
     * @param _moxieBondingCurve Address of the moxie bonding curve.
     * @param _moxieToken Address of the moxie token.
     * @param _defaultAdmin Address of the staking admin.
     */
    function initialize(
        address _tokenManager,
        address _moxieBondingCurve,
        address _moxieToken,
        address _defaultAdmin
    ) external initializer {
        __AccessControl_init();
        __Pausable_init();

        _validateInput(
            _tokenManager,
            _moxieBondingCurve,
            _moxieToken,
            _defaultAdmin
        );

        tokenManager = ITokenManager(_tokenManager);
        moxieBondingCurve = IMoxieBondingCurve(_moxieBondingCurve);
        moxieToken = IERC20Extended(_moxieToken);
        _grantRole(DEFAULT_ADMIN_ROLE, _defaultAdmin);
    }

    /**
     * @dev Modifier to check if the lock period is allowed.
     * @param _lockPeriod Lock period to check.
     */
    modifier onlyValidLockPeriod(uint256 _lockPeriod) {
        if (!lockPeriodsInSec[_lockPeriod]) {
            revert Staking_InvalidLockPeriod();
        }
        _;
    }

    /**
     * @dev Internal function to validate initialization input.
     * @param _tokenManager Address of the token manager.
     * @param _moxieBondingCurve Address of the moxie bonding curve.
     * @param _moxieToken Address of the moxie token.
     * @param _defaultAdmin Address of the staking admin.
     */
    function _validateInput(
        address _tokenManager,
        address _moxieBondingCurve,
        address _moxieToken,
        address _defaultAdmin
    ) internal pure {
        if (_isZeroAddress(_tokenManager)) {
            revert Staking_InvalidTokenManager();
        }
        if (_isZeroAddress(_moxieBondingCurve)) {
            revert Staking_InvalidMoxieBondingCurve();
        }
        if (_isZeroAddress(_moxieToken)) {
            revert Staking_InvalidMoxieToken();
        }
        if (_isZeroAddress(_defaultAdmin)) {
            revert Staking_InvalidDefaultAdmin();
        }
    }

    /**
     * @dev Internal function to validate address.
     * @param _address  Address to validate.
     */
    function _isZeroAddress(address _address) internal pure returns (bool) {
        return _address == address(0);
    }

    /**
     * Created lock for a deposit.
     * @param _subject subject address for which tokens are getting deposited.
     * @param _amount Amount of tokens getting deposited.
     * @param _lockPeriodInSec Lock period for the tokens.
     * @param _beneficiary Address of the beneficiary for the lock.
     * @param _unlockTimeInSec Unlock time of lock in secs.
     * @param _moxieDepositAmount Amount of moxie tokens deposited for buying.
     */
    function _createLock(
        address _subject,
        uint256 _amount,
        uint256 _lockPeriodInSec,
        uint256 _unlockTimeInSec,
        address _beneficiary,
        uint256 _moxieDepositAmount
    )
        internal
        returns (IERC20Extended _subjectToken)
    {
        if (_isZeroAddress(_subject)) {
            revert Staking_InvalidSubject();
        }
        if (_amount == 0) {
            revert Staking_AmountShouldBeGreaterThanZero();
        }
        if (_isZeroAddress(_beneficiary)) {
            revert Staking_InvalidBeneficiary();
        }
        _subjectToken = IERC20Extended(tokenManager.tokens(_subject));
        if (address(_subjectToken) == address(0)) {
            revert Staking_InvalidSubjectToken();
        }
        uint256 _index = lockCount++;
        LockInfo memory lockInfo = LockInfo({
            amount: _amount,
            unlockTimeInSec: _unlockTimeInSec,
            subject: _subject,
            subjectToken: address(_subjectToken),
            user: _beneficiary,
            lockPeriodInSec: _lockPeriodInSec
        });
        // lock the tokens
        locks[_index] = lockInfo;

        emit Lock(
            _beneficiary,
            _subject,
            address(_subjectToken),
            _index,
            _amount,
            _unlockTimeInSec,
            _lockPeriodInSec,
            _moxieDepositAmount == 0 ? address(0) : msg.sender,
            _moxieDepositAmount
        );
    }

    /**
     * @notice Extracts expired locks and deletes them.
     * @param _subject Subject address for which locks are being extracted.
     * @param _indexes Indexes of the locks to be extracted.
     * @return subjectToken_ Address of the subject token.
     * @return totalAmount_ Total amount of tokens withdrawn.
     */
    function _extractExpiredAndDeleteLocks(
        address _subject,
        uint256[] memory _indexes
    ) internal returns (address subjectToken_, uint256 totalAmount_) {
        if (_isZeroAddress(_subject)) {
            revert Staking_InvalidSubject();
        }

        if (_indexes.length == 0) {
            revert Staking_EmptyIndexes();
        }
        LockInfo memory lockInfo = locks[_indexes[0]];
        subjectToken_ = lockInfo.subjectToken;

        for (uint256 i = 0; i < _indexes.length; i++) {
            uint256 index = _indexes[i];
            lockInfo = locks[index];
            if (lockInfo.subject != _subject) {
                revert Staking_SubjectsDoesNotMatch(index);
            }
            if (lockInfo.unlockTimeInSec > block.timestamp) {
                revert Staking_LockNotExpired(
                    index,
                    block.timestamp,
                    lockInfo.unlockTimeInSec
                );
            }
            if (lockInfo.user != msg.sender) {
                revert Staking_NotOwner(index);
            }
            totalAmount_ += lockInfo.amount;
            delete locks[index];
        }
    }

    /**
     * @notice Deposits and locks tokens for a single subject.
     * @param _subject Subject address for which tokens are being deposited.
     * @param _amount Amount of tokens being deposited.
     * @param _lockPeriodInSec Lock period for the tokens.
     * @param _unlockTimeInSec Unlock time of lock in secs.
     * @param _beneficiary Beneficiary of the lock. 
     */
    function _depositAndLock(
        address _subject,
        uint256 _amount,
        uint256 _lockPeriodInSec,
        uint256 _unlockTimeInSec,
        address _beneficiary
    ) internal  {
        IERC20Extended subjectToken;
        (subjectToken) = _createLock(
            _subject,
            _amount,
            _lockPeriodInSec,
            _unlockTimeInSec,
            _beneficiary,
            0
        );

        // Transfer the tokens to this contract
        subjectToken.safeTransferFrom(msg.sender, address(this), _amount);
    }

    /**
     * @notice Calculates unlock time.
     * @param _lockPeriodInSec Lock period to set.
     * @return unlock time in sec
     */
    function _getUnlockTime(uint256 _lockPeriodInSec) internal view returns(uint256) {
        return block.timestamp + _lockPeriodInSec;
    }

    /**
     * @notice Sets the lock period for staking. only owner can call this function.
     * @param _lockPeriodInSec Lock period to set.
     * @param _allowed Boolean to allow or disallow the lock period.
     */
    function setLockPeriod(
        uint256 _lockPeriodInSec,
        bool _allowed
    ) external onlyRole(CHANGE_LOCK_DURATION) {
        if (lockPeriodsInSec[_lockPeriodInSec] == _allowed) {
            revert Staking_LockPeriodAlreadySet();
        }
        lockPeriodsInSec[_lockPeriodInSec] = _allowed;
        emit LockPeriodUpdated(_lockPeriodInSec, _allowed);
    }

    /**
     * External function to deposit and lock tokens.
     * @param _subject Subject address for which tokens are getting deposited.
     * @param _amount amount of tokens getting deposited.
     * @param _lockPeriodInSec lock period for the tokens.
     * @return unlockTimeInSec_ Unlock times for the locks.
     */
    function depositAndLock(
        address _subject,
        uint256 _amount,
        uint256 _lockPeriodInSec
    )
        external
        whenNotPaused
        onlyValidLockPeriod(_lockPeriodInSec)
        returns (uint256 unlockTimeInSec_)
    {

        unlockTimeInSec_ = _getUnlockTime(_lockPeriodInSec);

        _depositAndLock(
            _subject,
            _amount,
            _lockPeriodInSec,
            unlockTimeInSec_,
            msg.sender
        );
    }

    /**
     * External function to deposit and lock tokens for a beneficiary.
     * @param _subject Subject address for which tokens are getting deposited.
     * @param _amount amount of tokens getting deposited.
     * @param _lockPeriodInSec lock period for the tokens.
     * @param _beneficiary Address of the beneficiary for the lock.
     * @return unlockTimeInSec_ Unlock times for the locks.
     */
    function depositAndLockFor(
        address _subject,
        uint256 _amount,
        uint256 _lockPeriodInSec,
        address _beneficiary
    )
        external
        whenNotPaused
        onlyValidLockPeriod(_lockPeriodInSec)
        returns (uint256 unlockTimeInSec_)
    {

        unlockTimeInSec_ = _getUnlockTime(_lockPeriodInSec);

        _depositAndLock(
            _subject,
            _amount,
            _lockPeriodInSec,
            unlockTimeInSec_,
            _beneficiary
        );
    }

    /**
     * External function to deposit and lock multiple tokens.
     * @param _subjects Subject addresses for which tokens are getting deposited.
     * @param _amounts Amounts of tokens getting deposited.
     * @param _lockPeriodInSec Lock periods for the tokens.
     * @return unlockTimeInSec_ Unlock times for the locks.
     */
    function depositAndLockMultiple(
        address[] memory _subjects,
        uint256[] memory _amounts,
        uint256 _lockPeriodInSec
    )
        external
        whenNotPaused
        onlyValidLockPeriod(_lockPeriodInSec)
        returns (uint256 unlockTimeInSec_)
    {
        if (_subjects.length != _amounts.length) {
            revert Staking_InvalidInputLength();
        }


        unlockTimeInSec_ = _getUnlockTime(_lockPeriodInSec);

        for (uint256 i = 0; i < _subjects.length; i++) {
            _depositAndLock(
                _subjects[i],
                _amounts[i],
                _lockPeriodInSec,
                unlockTimeInSec_,
                msg.sender
            );
        }
    }

    /**
     * External function to deposit and lock multiple tokens.
     * @param _subjects Subject addresses for which tokens are getting deposited.
     * @param _amounts Amounts of tokens getting deposited.
     * @param _lockPeriodInSec Lock periods for the tokens.
     * @param _beneficiary Address of the beneficiary for the lock.
     * @return unlockTimeInSec_ Unlock times for the locks.
     */
    function depositAndLockMultipleFor(
        address[] memory _subjects,
        uint256[] memory _amounts,
        uint256 _lockPeriodInSec,
        address _beneficiary
    )
        external
        whenNotPaused
        onlyValidLockPeriod(_lockPeriodInSec)
        returns (uint256 unlockTimeInSec_)
    {
        if (_subjects.length != _amounts.length) {
            revert Staking_InvalidInputLength();
        }

        unlockTimeInSec_ = _getUnlockTime(_lockPeriodInSec);


        for (uint256 i = 0; i < _subjects.length; i++) {
            _depositAndLock(
                _subjects[i],
                _amounts[i],
                _lockPeriodInSec,
                unlockTimeInSec_,
                _beneficiary
            );
        }
    }

    /**
     * External function to buy & lock tokens.
     * @param _subject Subject address for which tokens are being bought & deposited.
     * @param _depositAmount amount of moxie tokens getting deposited.
     * @param _minReturnAmountAfterFee Slippage setting which determines minimum amount of tokens after fee.
     * @param _lockPeriodInSec Lock period for the tokens.
     * @return amount_ Amount of tokens bought & locked.
     * @return unlockTimeInSec_ Unlock times for the locks.
     */
    function buyAndLock(
        address _subject,
        uint256 _depositAmount,
        uint256 _minReturnAmountAfterFee,
        uint256 _lockPeriodInSec
    )
        external
        whenNotPaused
        onlyValidLockPeriod(_lockPeriodInSec)
        returns (uint256 amount_, uint256 unlockTimeInSec_)
    {
        moxieToken.safeTransferFrom(msg.sender, address(this), _depositAmount);
        moxieToken.approve(address(moxieBondingCurve), _depositAmount);
        amount_ = moxieBondingCurve.buyShares(
            _subject,
            _depositAmount,
            _minReturnAmountAfterFee
        );

        unlockTimeInSec_ = _getUnlockTime(_lockPeriodInSec);
        _createLock(
            _subject,
            amount_,
            _lockPeriodInSec,
            unlockTimeInSec_,
            msg.sender,
            _depositAmount
        );
    }

    /**
     * External function to buy & lock tokens.
     * @param _subject Subject address for which tokens are being bought & deposited.
     * @param _depositAmount amount of moxie tokens getting deposited.
     * @param _minReturnAmountAfterFee Slippage setting which determines minimum amount of tokens after fee.
     * @param _lockPeriodInSec Lock period for the tokens.
     * @param _beneficiary Address of the beneficiary for the lock.
     * @return amount_ Amount of tokens bought & locked.
     * @return unlockTimeInSec_ Unlock times for the locks.
     */
    function buyAndLockFor(
        address _subject,
        uint256 _depositAmount,
        uint256 _minReturnAmountAfterFee,
        uint256 _lockPeriodInSec,
        address _beneficiary
    )
        external
        whenNotPaused
        onlyValidLockPeriod(_lockPeriodInSec)
        returns (uint256 amount_, uint256 unlockTimeInSec_)
    {
        moxieToken.safeTransferFrom(msg.sender, address(this), _depositAmount);
        moxieToken.approve(address(moxieBondingCurve), _depositAmount);
        amount_ = moxieBondingCurve.buyShares(
            _subject,
            _depositAmount,
            _minReturnAmountAfterFee
        );

        unlockTimeInSec_ = _getUnlockTime(_lockPeriodInSec);

        _createLock(
            _subject,
            amount_,
            _lockPeriodInSec,
            unlockTimeInSec_,
            _beneficiary,
            _depositAmount
        );
    }

    /**
     * External function to buy & lock multiple tokens.
     * @param _subjects Subject addresses for which tokens are being bought & deposited.
     * @param _depositAmounts Amounts of moxie tokens getting deposited.
     * @param _minReturnAmountsAfterFee Slippage settings which determine minimum amounts of tokens after fee.
     * @param _lockPeriodInSec Lock periods for the tokens.
     * @return amounts_ Amounts of tokens bought & locked.
     * @return unlockTimeInSec_ Unlock times for the locks.
     */
    function buyAndLockMultiple(
        address[] memory _subjects,
        uint256[] memory _depositAmounts,
        uint256[] memory _minReturnAmountsAfterFee,
        uint256 _lockPeriodInSec
    )
        external
        whenNotPaused
        onlyValidLockPeriod(_lockPeriodInSec)
        returns (uint256[] memory amounts_, uint256 unlockTimeInSec_)
    {
        if (
            _subjects.length != _depositAmounts.length ||
            _subjects.length != _minReturnAmountsAfterFee.length
        ) {
            revert Staking_InvalidInputLength();
        }

        amounts_ = new uint256[](_subjects.length);

        uint256 totalDepositAmount = 0;

        for (uint256 i = 0; i < _subjects.length; i++) {
            totalDepositAmount += _depositAmounts[i];
        }

        moxieToken.safeTransferFrom(
            msg.sender,
            address(this),
            totalDepositAmount
        );
        moxieToken.approve(address(moxieBondingCurve), totalDepositAmount);

        unlockTimeInSec_ = _getUnlockTime(_lockPeriodInSec);

        for (uint256 i = 0; i < _subjects.length; i++) {
            uint256 amount = moxieBondingCurve.buyShares(
                _subjects[i],
                _depositAmounts[i],
                _minReturnAmountsAfterFee[i]
            );
            _createLock(
                _subjects[i],
                amount,
                _lockPeriodInSec,
                unlockTimeInSec_,
                msg.sender,
                _depositAmounts[i]
            );
            amounts_[i] = amount;
        }
    }

    /**
     * External function to buy & lock multiple tokens.
     * @param _subjects Subject addresses for which tokens are being bought & deposited.
     * @param _depositAmounts Amounts of moxie tokens getting deposited.
     * @param _minReturnAmountsAfterFee Slippage settings which determine minimum amounts of tokens after fee.
     * @param _lockPeriodInSec Lock periods for the tokens.
     * @param _beneficiary Address of the beneficiary for the lock.
     * @return amounts_ Amounts of tokens bought & locked.
     * @return unlockTimeInSec_ Unlock times for the locks.
     */
    function buyAndLockMultipleFor(
        address[] memory _subjects,
        uint256[] memory _depositAmounts,
        uint256[] memory _minReturnAmountsAfterFee,
        uint256 _lockPeriodInSec,
        address _beneficiary
    )
        external
        whenNotPaused
        onlyValidLockPeriod(_lockPeriodInSec)
        returns (uint256[] memory amounts_, uint256 unlockTimeInSec_)
    {
        if (
            _subjects.length != _depositAmounts.length ||
            _subjects.length != _minReturnAmountsAfterFee.length
        ) {
            revert Staking_InvalidInputLength();
        }

        uint256 totalDepositAmount = 0;

        for (uint256 i = 0; i < _subjects.length; i++) {
            totalDepositAmount += _depositAmounts[i];
        }

        moxieToken.safeTransferFrom(
            msg.sender,
            address(this),
            totalDepositAmount
        );
        moxieToken.approve(address(moxieBondingCurve), totalDepositAmount);

        amounts_ = new uint256[](_subjects.length);

        unlockTimeInSec_ = _getUnlockTime(_lockPeriodInSec);


        for (uint256 i = 0; i < _subjects.length; i++) {
            amounts_[i] = moxieBondingCurve.buyShares(
                _subjects[i],
                _depositAmounts[i],
                _minReturnAmountsAfterFee[i]
            );
            _createLock(
                _subjects[i],
                amounts_[i],
                _lockPeriodInSec,
                unlockTimeInSec_,
                _beneficiary,
                _depositAmounts[i]
            );
        }
    }

    /**
     * External function to withdraw locked tokens.
     * @param _subject Subject address for which tokens are being withdrawn.
     * @param _indexes Indexes of the locks to be withdrawn.
     * @return totalAmount_ Total amount of tokens withdrawn.
     */
    function withdraw(
        address _subject,
        uint256[] memory _indexes
    ) external whenNotPaused returns (uint256 totalAmount_) {
        address subjectTokenAddress;

        (subjectTokenAddress, totalAmount_) = _extractExpiredAndDeleteLocks(
            _subject,
            _indexes
        );

        IERC20Extended subjectToken = IERC20Extended(subjectTokenAddress);

        subjectToken.safeTransfer(msg.sender, totalAmount_);
        emit Withdraw(
            msg.sender,
            _subject,
            subjectTokenAddress,
            _indexes,
            totalAmount_
        );
    }

    /**
     * External function to extend the lock period of the tokens.
     * @param _subject Subject address for which tokens are being extended.
     * @param _indexes Indexes of the locks to be extended.
     * @param _lockPeriodInSec New lock period for the tokens.
     * @return totalAmount_ Total amount of tokens extended for lock.
     * @return unlockTimeInSec_ unlock time is the timestamp of the extended lock.
     */
    function extendLock(
        address _subject,
        uint256[] memory _indexes,
        uint256 _lockPeriodInSec
    )
        external
        whenNotPaused
        onlyValidLockPeriod(_lockPeriodInSec)
        returns (uint256 totalAmount_, uint256 unlockTimeInSec_)
    {
        address subjectToken;
        (subjectToken, totalAmount_) = _extractExpiredAndDeleteLocks(
            _subject,
            _indexes
        );
        emit LockExtended(
            msg.sender,
            _subject,
            subjectToken,
            _indexes,
            totalAmount_
        );

        unlockTimeInSec_ = _getUnlockTime(_lockPeriodInSec);

        _createLock(
            _subject,
            totalAmount_,
            _lockPeriodInSec,
            unlockTimeInSec_,
            msg.sender,
            0
        );

    }

    /**
     * External function to extend the lock period of the tokens.
     * @param _subject Subject address for which tokens are being extended.
     * @param _indexes Indexes of the locks to be extended.
     * @param _lockPeriodInSec New lock period for the tokens.
     * @param _beneficiary Address of the beneficiary for the lock.
     * @return totalAmount_ Total amount of tokens extended for lock.
     * @return unlockTimeInSec_ unlock time is the timestamp of the extended lock.
     */
    function extendLockFor(
        address _subject,
        uint256[] memory _indexes,
        uint256 _lockPeriodInSec,
        address _beneficiary
    )
        external
        whenNotPaused
        onlyValidLockPeriod(_lockPeriodInSec)
        returns (uint256 totalAmount_, uint256 unlockTimeInSec_)
    {
        address subjectToken;
        (subjectToken, totalAmount_) = _extractExpiredAndDeleteLocks(
            _subject,
            _indexes
        );
        emit LockExtended(
            msg.sender,
            _subject,
            subjectToken,
            _indexes,
            totalAmount_
        );

        unlockTimeInSec_ = _getUnlockTime(_lockPeriodInSec);

        _createLock(
            _subject,
            totalAmount_,
            _lockPeriodInSec,
            unlockTimeInSec_,
            _beneficiary,
            0
        );

    }

    /**
     * External function to get the total staked amount for a user & subject token.
     * @param _user User address for which total staked amount is being calculated.
     * @param _subject Subject address for which total staked amount is being calculated.
     * @param _indexes Indexes of the locks for which total staked amount is being calculated.
     */
    function getTotalStakedAmount(
        address _user,
        address _subject,
        uint256[] calldata _indexes
    ) external view returns (uint256 totalAmount_) {
        for (uint256 i = 0; i < _indexes.length; i++) {
            uint256 _index = _indexes[i];
            LockInfo memory lockInfo = locks[_index];
            if (lockInfo.user != _user) {
                revert Staking_NotSameUser(_index);
            }
            if (lockInfo.subject != _subject) {
                revert Staking_SubjectsDoesNotMatch(_index);
            }
            totalAmount_ += lockInfo.amount;
        }
    }
}

contracts/SubjectFactory.sol.content:
// SPDX-License-Identifier: GPL-3.0-or-later
pragma solidity ^0.8.24;

import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

import {SecurityModule} from "./SecurityModule.sol";
import {ISubjectFactory} from "./interfaces/ISubjectFactory.sol";
import {ITokenManager} from "./interfaces/ITokenManager.sol";
import {IMoxieBondingCurve} from "./interfaces/IMoxieBondingCurve.sol";
import {IEasyAuction} from "./interfaces/IEasyAuction.sol";
import {IERC20Extended} from "./interfaces/IERC20Extended.sol";

contract SubjectFactory is SecurityModule, ISubjectFactory {
    using SafeERC20 for IERC20Extended;

    bytes32 public constant ONBOARDING_ROLE = keccak256("ONBOARDING_ROLE");
    bytes32 public constant UPDATE_BENEFICIARY_ROLE =
        keccak256("UPDATE_BENEFICIARY_ROLE");
    bytes32 public constant UPDATE_FEES_ROLE = keccak256("UPDATE_FEES_ROLE");
    bytes32 public constant UPDATE_AUCTION_ROLE =
        keccak256("UPDATE_AUCTION_ROLE");

    /// @dev Represent Percentage for fee 0% = 0; 1% = 10 ** 16; 100% = 10 ** 18
    uint256 public constant PCT_BASE = 10 ** 18;

    error SubjectFactory_InvalidBeneficiary();
    error SubjectFactory_InvalidFeePercentage();
    error SubjectFactory_InvalidSubject();
    error SubjectFactory_InvalidTokenManager();
    error SubjectFactory_InvalidMoxieBondingCurve();
    error SubjectFactory_InvalidToken();
    error SubjectFactory_InvalidAuctionDuration();
    error SubjectFactory_InvalidAuctionOrderCancellationDuration();
    error SubjectFactory_InvalidAuctionContract();
    error SubjectFactory_AuctionAlreadyCreated();
    error SubjectFactory_AuctionNotCreated();
    error SubjectFactory_AuctionNotDoneYet();
    error SubjectFactory_InvalidOwner();
    error SubjectFactory_InvalidReserveRatio();
    error SubjectFactory_BuyAmountTooLess();

    ITokenManager public tokenManager;
    IMoxieBondingCurve public moxieBondingCurve;
    uint256 public protocolFeePct;
    uint256 public subjectFeePct;

    address public feeBeneficiary;
    IEasyAuction public easyAuction;

    uint256 public auctionDuration;
    uint256 public auctionOrderCancellationDuration;

    IERC20Extended public token;

    mapping(address subject => Auction auction) public auctions;

    /**
     * @dev Initialize the contract.
     * @param _owner Owner of the contract;
     * @param _tokenManager Address of token manager contract.
     * @param _moxieBondingCurve  Address of Bonding curve contract.
     * @param _token  Address of moxie token.
     * @param _easyAuction Address of Easy auction contract.
     * @param _feeInput Fee input struct
     * @param _feeBeneficiary Protocol fee beneficiary.
     * @param _auctionDuration Duration of auction in unixtimestamp.
     * @param _auctionOrderCancellationDuration  duration of auction order  cancellation in unixtimestamp.
     */
    function initialize(
        address _owner,
        address _tokenManager,
        address _moxieBondingCurve,
        address _token,
        address _easyAuction,
        FeeInput memory _feeInput,
        address _feeBeneficiary,
        uint256 _auctionDuration,
        uint256 _auctionOrderCancellationDuration
    ) external initializer {
        if (_owner == address(0)) revert SubjectFactory_InvalidOwner();

        if (_tokenManager == address(0))
            revert SubjectFactory_InvalidTokenManager();
        if (_moxieBondingCurve == address(0))
            revert SubjectFactory_InvalidMoxieBondingCurve();
        if (_token == address(0)) revert SubjectFactory_InvalidToken();
        if (_easyAuction == address(0))
            revert SubjectFactory_InvalidAuctionContract();

        if (!_feeIsValid(_feeInput.protocolFeePct + _feeInput.subjectFeePct))
            revert SubjectFactory_InvalidFeePercentage();

        if (!_feeBeneficiaryIsValid(_feeBeneficiary))
            revert SubjectFactory_InvalidBeneficiary();

        if (_auctionOrderCancellationDuration == 0)
            revert SubjectFactory_InvalidAuctionOrderCancellationDuration();

        if (_auctionDuration < _auctionOrderCancellationDuration)
            revert SubjectFactory_InvalidAuctionDuration();

        protocolFeePct = _feeInput.protocolFeePct;
        subjectFeePct = _feeInput.subjectFeePct;
        feeBeneficiary = _feeBeneficiary;
        token = IERC20Extended(_token);
        auctionDuration = _auctionDuration;
        auctionOrderCancellationDuration = _auctionOrderCancellationDuration;
        easyAuction = IEasyAuction(_easyAuction);
        tokenManager = ITokenManager(_tokenManager);
        moxieBondingCurve = IMoxieBondingCurve(_moxieBondingCurve);

        _grantRole(DEFAULT_ADMIN_ROLE, _owner);
    }

    /**
     * @dev check if fee is valid.
     * @param _fee Fee percentage in PCT_BASE.
     */
    function _feeIsValid(uint256 _fee) internal pure returns (bool) {
        return _fee < PCT_BASE;
    }

    /**
     * @dev Check if fee beneficiary is valid.
     * @param _beneficiary Address of beneficiary.
     */
    function _feeBeneficiaryIsValid(
        address _beneficiary
    ) internal pure returns (bool) {
        return _beneficiary != address(0);
    }

    /**
     * @dev update fee beneficiary
     * @param _beneficiary Address of beneficiary.
     */
    function _updateFeeBeneficiary(address _beneficiary) internal {
        feeBeneficiary = _beneficiary;

        emit UpdateBeneficiary(_beneficiary);
    }

    /**
     * @dev Update fee params
     * @param _protocolFeePct Protocol fee in PCT.
     * @param _subjectFeePct Subject fee in PCT.
     */
    function _updateFees(
        uint256 _protocolFeePct,
        uint256 _subjectFeePct
    ) internal {
        protocolFeePct = _protocolFeePct;
        subjectFeePct = _subjectFeePct;

        emit UpdateFees(protocolFeePct, subjectFeePct);
    }

    /**
     * @dev Create auction for a subject.
     * @param _subject Address of subject.
     * @param _auctionInput Input params for auction.
     * @return auctionId_ Auction Id.
     * @return auctionEndDate_ Auction end date.
     */
    function _createAuction(
        address _subject,
        address _subjectToken,
        SubjectAuctionInput memory _auctionInput
    ) internal returns (uint256 auctionId_, uint256 auctionEndDate_) {
        auctionEndDate_ = block.timestamp + auctionDuration;
        auctions[_subject].auctionEndDate = auctionEndDate_;
        auctions[_subject].initialSupply = _auctionInput.initialSupply;
        auctionId_ = easyAuction.initiateAuction(
            _subjectToken,
            address(token),
            block.timestamp + auctionOrderCancellationDuration,
            auctionEndDate_,
            _auctionInput.initialSupply,
            _auctionInput.minBuyAmount,
            _auctionInput.minBiddingAmount,
            _auctionInput.minFundingThreshold,
            _auctionInput.isAtomicClosureAllowed,
            _auctionInput.accessManagerContract,
            _auctionInput.accessManagerContractData
        );

        auctions[_subject].auctionId = auctionId_;
    }

    /**
     * @dev Decode the clearing order from auction.
     * @param _orderData Orderdata returned from easy auction contract.
     * @return userId UserId in auction contract. Not needed.
     * @return buyAmount Amount of Moxie token.
     * @return sellAmount Amount of Subject Token.
     */
    function _decodeOrder(
        bytes32 _orderData
    )
        internal
        pure
        returns (uint64 userId, uint96 buyAmount, uint96 sellAmount)
    {
        // Note: converting to uint discards the binary digits that do not fit
        // the type.
        userId = uint64(uint256(_orderData) >> 192);
        buyAmount = uint96(uint256(_orderData) >> 96);
        sellAmount = uint96(uint256(_orderData));
    }

    /**
     * @dev Close auction & burn tokens which are not sold in auction.
     * @param _auctionId Auction Id.
     * @param _initialSupply Initial supply of auction.
     * @return soldSupply_ Total supply that got sold.
     * @return amountRaised_ Amount of moxie raised.
     * @return clearingOrder Clearning order to calculate price of auction.
     */
    function _closeAuction(
        uint256 _auctionId,
        address _subject,
        uint256 _initialSupply
    )
        internal
        returns (
            uint256 soldSupply_,
            uint256 amountRaised_,
            bytes32 clearingOrder
        )
    {
        address subjectToken = tokenManager.tokens(_subject);
        uint256 beforeBalanceInSubjectToken = IERC20Extended(subjectToken)
            .balanceOf(address(this));
        uint256 beforeBalanceInMoxieToken = IERC20Extended(token).balanceOf(
            address(this)
        );

        clearingOrder = easyAuction.settleAuction(_auctionId);

        uint256 afterBalanceInSubjectToken = IERC20Extended(subjectToken)
            .balanceOf(address(this));
        uint256 afterBalanceInMoxieToken = IERC20Extended(token).balanceOf(
            address(this)
        );

        soldSupply_ =
            _initialSupply -
            (afterBalanceInSubjectToken - beforeBalanceInSubjectToken);
        amountRaised_ = afterBalanceInMoxieToken - beforeBalanceInMoxieToken;

        uint256 amountToBurn = _initialSupply - soldSupply_;

        // Burn subject token which are not sold in auction.
        if (amountToBurn > 0) {
            IERC20Extended(subjectToken).burn(amountToBurn);
        }
    }

    /**
     * @dev Internal function to calculate fees.
     * @param _amount Amount against fee should be calculated..
     * @return protocolFee_ protocol fee in PCT_BASE.
     * @return subjectFee_  subject fee in PCT_BASE.
     */
    function _calculateFee(
        uint256 _amount
    ) internal view returns (uint256 protocolFee_, uint256 subjectFee_) {
        protocolFee_ = (_amount * protocolFeePct) / PCT_BASE;
        subjectFee_ = (_amount * subjectFeePct) / PCT_BASE;
    }

    /**
     * @dev Calculate Tokens to mint for given input amount based on auction price.
     * @param _clearingOrder Clearing order from auction.
     * @param _amount Amount of reserve tokens from onboarding.
     */
    function _calculateTokensMintAfterAuction(
        bytes32 _clearingOrder,
        uint256 _amount
    ) internal pure returns (uint256) {
        /// @dev buyAmount is subject token amount & sell amount is moxie token.
        (, uint96 buyAmount, uint96 sellAmount) = _decodeOrder(_clearingOrder);
        return (buyAmount * _amount) / sellAmount;
    }

    /**
     * @dev Initialize Bonding curve ,also mint bonding supply for onboarding reserve amount.
     * @param _auctionId Auction Id from easy auction contract for subject onboarding.
     * @param _subject Address of subject.
     * @param _amountRaised Amount raised in auction.
     * @param _supply Total supply sold in auction.
     * @param _reserveRatio Reserve ratio for Bonding curve.
     * @param _clearningOrder Clearing order from auction.
     * @param _buyAmount Amount to mint shares to this contract at auction price.
     */
    function _initializeBondingCurve(
        uint256 _auctionId,
        address _subject,
        uint256 _amountRaised,
        uint256 _supply,
        uint32 _reserveRatio,
        bytes32 _clearningOrder,
        uint256 _buyAmount
    ) internal {
        uint256 newSupplyToMint = _calculateTokensMintAfterAuction(
            _clearningOrder,
            _buyAmount
        );

        if (newSupplyToMint == 0) {
            revert SubjectFactory_BuyAmountTooLess();
        }
        /// @dev this supply will always be locked in this  contract to make sure Bonding curve always have non zero price.
        tokenManager.mint(_subject, address(this), newSupplyToMint);

        (uint256 protocolFee_, uint256 subjectFee_) = _calculateFee(
            _amountRaised + _buyAmount // total amount is sum of auction amount + reserve amount from onboarding flow.
        );
        uint256 bondingAmount_ = _amountRaised +
            _buyAmount -
            protocolFee_ -
            subjectFee_;

        // approve bonding curve to spend moxie
        token.approve(address(moxieBondingCurve), bondingAmount_);

        uint256 bondingSupply_ = _supply + newSupplyToMint;
        moxieBondingCurve.initializeSubjectBondingCurve(
            _subject,
            _reserveRatio,
            bondingSupply_,
            bondingAmount_
        );

        token.safeTransfer(feeBeneficiary, protocolFee_);

        uint256 subjectFeeInSubjectToken = 0;
        ///@dev Instead of returning subject fee to subject, give buy subject shares for subject.
        if (subjectFee_ > 0) {
            token.approve(address(moxieBondingCurve), subjectFee_);
            subjectFeeInSubjectToken = moxieBondingCurve.buySharesFor(
                _subject,
                subjectFee_,
                _subject,
                0 //slippage settings not needed as this is first buy transaction.
            );
        }

        emit SubjectOnboardingFinished(
            _subject,
            tokenManager.tokens(_subject),
            _auctionId,
            bondingSupply_,
            bondingAmount_,
            protocolFee_,
            subjectFee_,
            subjectFeeInSubjectToken
        );
    }

    /**
     * @dev Function to onboard & start auction of initial supply of subject.
     * @param _subject Address of subject.
     * @param _auctionInput Input for auction creation.
     */
    function initiateSubjectOnboarding(
        address _subject,
        SubjectAuctionInput memory _auctionInput
    ) external whenNotPaused onlyRole(ONBOARDING_ROLE) returns (uint256) {
        if (_subject == address(0)) revert SubjectFactory_InvalidSubject();

        if (auctions[_subject].auctionId != 0)
            revert SubjectFactory_AuctionAlreadyCreated();

        address subjectToken = tokenManager.create(
            _subject,
            _auctionInput.name,
            _auctionInput.symbol,
            _auctionInput.initialSupply,
            _auctionInput.accessManagerContract
        );

        IERC20Extended(subjectToken).approve(
            address(easyAuction),
            _auctionInput.initialSupply
        );

        (uint256 auctionId, uint256 auctionEndDate) = _createAuction(
            _subject,
            subjectToken,
            _auctionInput
        );

        emit SubjectOnboardingInitiated(
            _subject,
            subjectToken,
            _auctionInput.initialSupply,
            address(token),
            auctionEndDate,
            auctionId
        );
        return auctionId;
    }

    /**
     * @dev Finalize subject onboarding.
     *  1. Close auction
     *  2. Burn unsold supply
     *  3. Calculate additional mint for onboarding reserve
     *  4. Calculate & transfer fee.
     *  5. Initiate bonding curve.
     * @param _subject Address of subject token.
     * @param _buyAmount Amount of tokens contract will use to buy shares of subject token after auction is done.
     * This is to make sure there is always a supply before initiating bonding curve. Subject token against this
     * reserve will be locked in this contract forever.
     * @param _reserveRatio Reserve ratio of bonding curve.
     */
    function finalizeSubjectOnboarding(
        address _subject,
        uint256 _buyAmount,
        uint32 _reserveRatio
    ) external whenNotPaused onlyRole(ONBOARDING_ROLE) {
        if (_subject == address(0)) revert SubjectFactory_InvalidSubject();
        if (_reserveRatio == 0) revert SubjectFactory_InvalidReserveRatio();

        Auction memory auction = auctions[_subject];
        delete auctions[_subject];
        uint256 auctionId = auction.auctionId;

        if (auctionId == 0) revert SubjectFactory_AuctionNotCreated();

        if (block.timestamp < auction.auctionEndDate)
            revert SubjectFactory_AuctionNotDoneYet();

        (
            uint256 soldSupply,
            uint256 amountRaised,
            bytes32 clearingOrder
        ) = _closeAuction(auctionId, _subject, auction.initialSupply);
        // transfer buy amount from caller to contract.
        token.safeTransferFrom(msg.sender, address(this), _buyAmount);

        _initializeBondingCurve(
            auctionId,
            _subject,
            amountRaised,
            soldSupply,
            _reserveRatio,
            clearingOrder,
            _buyAmount
        );
    }

    /**
     * @notice Update beneficiary to `_beneficiary. It can be done by UPDATE_BENEFICIARY_ROLE.
     * @param _feeBeneficiary The address of the new beneficiary [to whom fees are to be sent]
     */
    function updateFeeBeneficiary(
        address _feeBeneficiary
    ) external onlyRole(UPDATE_BENEFICIARY_ROLE) {
        if (!_feeBeneficiaryIsValid(_feeBeneficiary))
            revert SubjectFactory_InvalidBeneficiary();

        _updateFeeBeneficiary(_feeBeneficiary);
    }

    /**
     * @notice Update fee only be called by role UPDATE_FEES_ROLE.
     * @param _feeInput Fee input struct.
     */
    function updateFees(
        FeeInput memory _feeInput
    ) external onlyRole(UPDATE_FEES_ROLE) {
        if (!_feeIsValid(_feeInput.protocolFeePct + _feeInput.subjectFeePct))
            revert SubjectFactory_InvalidFeePercentage();

        _updateFees(_feeInput.protocolFeePct, _feeInput.subjectFeePct);
    }

    /**
     * @notice Update auction params.
     * @param _auctionDuration Duration of auction in timestamp.
     * @param _auctionOrderCancellationDuration  Duration on order cancellation in timestamp.
     */
    function updateAuctionTime(
        uint256 _auctionDuration,
        uint256 _auctionOrderCancellationDuration
    ) external onlyRole(UPDATE_AUCTION_ROLE) {
        if (_auctionOrderCancellationDuration == 0)
            revert SubjectFactory_InvalidAuctionOrderCancellationDuration();

        if (_auctionDuration < _auctionOrderCancellationDuration)
            revert SubjectFactory_InvalidAuctionDuration();

        auctionDuration = _auctionDuration;
        auctionOrderCancellationDuration = _auctionOrderCancellationDuration;

        emit UpdateAuctionParam(
            _auctionDuration,
            _auctionOrderCancellationDuration
        );
    }
}

